'use client';

import { useState } from 'react';
import { Symbol } from '@/types';
import { Watchlist } from './Watchlist';
import { SymbolDetails } from './SymbolDetails';

interface RightSidebarProps {
  watchlistSymbols: Symbol[];
  selectedSymbol: Symbol;
  onSymbolSelect: (symbol: Symbol) => void;
  isCollapsed: boolean;
  onCollapsedChange: (collapsed: boolean) => void;
}

export const RightSidebar: React.FC<RightSidebarProps> = ({
  watchlistSymbols,
  selectedSymbol,
  onSymbolSelect,
  isCollapsed,
  onCollapsedChange,
}) => {
  const [activeTab, setActiveTab] = useState<'watchlist' | 'details'>('watchlist');

  return (
    <aside
      className={`fixed right-0 top-16 bottom-0 glass border-l transition-all duration-300 overflow-hidden ${
        isCollapsed ? 'w-0' : 'w-80'
      }`}
      style={{ top: '64px' }}
    >
      {!isCollapsed && (
        <div className="h-full flex flex-col">
          {/* Header */}
          <div className="flex items-center justify-between px-4 py-3 border-b border-border">
            <div className="flex gap-2">
              <button
                onClick={() => setActiveTab('watchlist')}
                className={`text-sm font-medium pb-2 border-b-2 transition-colors ${
                  activeTab === 'watchlist'
                    ? 'text-foreground border-primary'
                    : 'text-muted border-transparent hover:text-foreground'
                }`}
              >
                Watchlist
              </button>
              <button
                onClick={() => setActiveTab('details')}
                className={`text-sm font-medium pb-2 border-b-2 transition-colors ${
                  activeTab === 'details'
                    ? 'text-foreground border-primary'
                    : 'text-muted border-transparent hover:text-foreground'
                }`}
              >
                Details
              </button>
            </div>

            <button
              onClick={() => onCollapsedChange(true)}
              className="icon-button"
              title="Collapse"
            >
              ✕
            </button>
          </div>

          {/* Content */}
          <div className="flex-1 overflow-y-auto">
            {activeTab === 'watchlist' && (
              <Watchlist
                watchlistSymbols={watchlistSymbols}
                selectedSymbol={selectedSymbol.symbol}
                onSymbolSelect={onSymbolSelect}
              />
            )}
            {activeTab === 'details' && (
              <SymbolDetails symbol={selectedSymbol} />
            )}
          </div>
        </div>
      )}

      {isCollapsed && (
        <button
          onClick={() => onCollapsedChange(false)}
          className="absolute right-0 top-4 -left-10 z-50 icon-button"
          title="Expand"
        >
          ◀
        </button>
      )}
    </aside>
  );
};
